private let maxLine = 120
private let header =
    "// Generated by Tools/gen-track from proto/common/events/v1. Do not edit: run `make typed-track`."

// Events Pug tracks on its own get no method: tracking one would count it twice, and a screenView()
// would look like Pug.screen() without moving the current screen.
private let sdkTracked: Set<String> = ["app_open", "app_close", "app_install", "app_update", "screen_view"]

private let trackNamespaceDoc = [
    "Pug's well-known events as typed calls: `Pug.track.addToCart(productId: \"p1\", price: 9.99)` tracks "
        + "`add_to_cart` with those properties. Parameters without a default are the properties the event "
        + "requires, one left `nil` is not sent, and a duration is a `TimeInterval`, sent as text such as "
        + "`\"1.5s\"`. `extras` adds properties; a parameter that is set wins over an extra of its name.",
    "",
    "The events Pug tracks itself have no method: `app_open`, `app_close`, `app_install`, `app_update` and "
        + "`screen_view`.",
]

private let eventsDoc =
    "The kinds of Pug's well-known events. ``TrackNamespace`` has a typed method for each but those Pug tracks "
    + "itself."

/// The generated sources, by file name.
func render(_ events: [Event]) -> [(name: String, source: String)] {
    [
        ("Events.swift", eventKinds(events)),
        ("TrackNamespace.swift", trackNamespace(events)),
        ("WellKnownEvents.swift", wellKnownEvents(events)),
    ]
}

private func eventKinds(_ events: [Event]) -> String {
    var source = Source()
    source.line(header)
    source.line()
    source.line("extension Pug {")
    source.doc("    ", wrap(eventsDoc, indent: "    "))
    source.line("    public enum Events {")
    for event in events {
        source.line("        public static let \(event.name) = \"\(event.kind)\"")
    }
    source.line("    }")
    source.line("}")
    return source.text
}

private func trackNamespace(_ events: [Event]) -> String {
    let typed = events.filter { !sdkTracked.contains($0.kind) }
    var source = Source()
    source.line(header)
    source.line()
    if typed.contains(where: { $0.fields.contains { $0.type == .duration } }) {
        source.line("import Foundation")
        source.line()
    }
    source.line("extension Pug {")
    source.doc("    ", trackNamespaceDoc.flatMap { $0.isEmpty ? [$0] : wrap($0, indent: "    ") })
    source.line("    public struct TrackNamespace: Sendable {")
    source.line("        let facade: any TypedTracking")
    for event in typed {
        source.line()
        source.method(event)
    }
    source.line("    }")
    source.line("}")
    return source.text
}

private func wellKnownEvents(_ events: [Event]) -> String {
    var source = Source()
    source.line(header)
    source.line()
    source.doc("", ["The schema of each well-known event, for typed tracking and the checks on untyped events."])
    source.line("enum WellKnownEvents {")
    for event in events {
        // Only TrackNamespace reads a schema by name; the events Pug tracks itself live in byKind alone.
        let access = sdkTracked.contains(event.kind) ? "private " : ""
        var arguments: [Code] = [.text("kind: Pug.Events.\(event.name)"), .text("method: \"\(event.name)\"")]
        if !event.fields.isEmpty {
            arguments.append(.list("fields: [", event.fields.map { .text(schema($0)) }, "]", trailingComma: true))
        }
        source.code(.list("\(access)static let \(event.name) = EventSchema(", arguments, ")"), indent: "    ")
    }
    source.line()
    source.code(.list("static let all = [", events.map { .text($0.name) }, "]", trailingComma: true), indent: "    ")
    source.line()
    source.line(
        "    static let byKind = Dictionary(all.map { ($0.kind, $0) }, uniquingKeysWith: { first, _ in first })")
    source.line("}")
    return source.text
}

private func schema(_ field: Field) -> String {
    let required = field.required ? ", required: true" : ""
    return "FieldSchema(\"\(field.key)\", \(field.type.schemaCase)\(required))"
}

/// Code as swift-format lays it out: on one line when it fits, else one item per line. swift-format
/// breaks a list that closes a line at exactly the line length, so a fit leaves a column spare.
private enum Code {
    case text(String)
    case list(_ open: String, _ items: [Code], _ close: String, trailingComma: Bool = false)

    var flat: String {
        switch self {
        case .text(let text):
            return text
        case .list(let open, let items, let close, _):
            return open + items.map(\.flat).joined(separator: ", ") + close
        }
    }

    func lines(indent: String, suffix: String = "") -> [String] {
        let line = indent + flat + suffix
        guard case .list(let open, let items, let close, let trailingComma) = self, line.count >= maxLine else {
            return [line]
        }
        var lines = [indent + open]
        for (index, item) in items.enumerated() {
            let last = index == items.count - 1
            lines += item.lines(indent: indent + "    ", suffix: last && !trailingComma ? "" : ",")
        }
        lines.append(indent + close + suffix)
        return lines
    }
}

private struct Source {
    private(set) var text = ""

    mutating func line(_ line: String = "") {
        text += line + "\n"
    }

    mutating func doc(_ indent: String, _ lines: [String]) {
        for line in lines {
            self.line(line.isEmpty ? "\(indent)///" : "\(indent)/// \(line)")
        }
    }

    mutating func code(_ code: Code, indent: String) {
        for line in code.lines(indent: indent) {
            self.line(line)
        }
    }

    mutating func method(_ event: Event) {
        var doc = ["Tracks `\(event.kind)`."]
        if !event.comment.isEmpty {
            doc += [""] + event.comment
        }
        let personal = event.fields.filter(\.pii).map {
            "- Parameter \($0.key): Personal data, as the schema marks it."
        }
        if !personal.isEmpty {
            doc += [""] + personal
        }
        self.doc("        ", doc)
        let parameters = event.fields.map { field in
            Code.text("\(field.key): \(field.type.swiftType)" + (field.required ? "" : "? = nil"))
        }
        let signature = parameters + [.text("extras: [String: Any]? = nil"), .text("options: TrackOptions? = nil")]
        code(.list("public func \(event.name)(", signature, ") {"), indent: "        ")
        let values = Code.list("[", event.fields.map { .text($0.key) }, "]", trailingComma: true)
        let arguments: [Code] = [
            .text("WellKnownEvents.\(event.name)"), values, .text("extras: extras"), .text("options: options"),
        ]
        code(.list("facade.trackTyped(", arguments, ")"), indent: "            ")
        line("        }")
    }
}

/// `text` as doc comment lines that fit under `indent`.
private func wrap(_ text: String, indent: String) -> [String] {
    let width = maxLine - indent.count - "/// ".count
    var lines: [String] = []
    var current = ""
    for word in text.split(separator: " ") {
        if !current.isEmpty && current.count + 1 + word.count > width {
            lines.append(current)
            current = String(word)
        } else {
            current += current.isEmpty ? String(word) : " \(word)"
        }
    }
    lines.append(current)
    return lines
}
